Bool HordeAIUpdate::isClearToApproach(const Object *docker) const
{
	HordeContainInterface *horde = getObject()->getContain()->getHordeContainInterface();
	if (!horde)
		return false;
	return horde->hasSpotForUnit(docker);
}

// FUNCTION: BFME2 0x0049A8A1 size=89 name=?reserveApproachPosition@HordeAIUpdate@@UAE_NHPAUCoord3D@@PAH@Z evidence=N:ledger
Bool HordeAIUpdate::reserveApproachPosition(Object *docker, Coord3D *position, Int *index)
{
	HordeContainInterface *horde = getObject()->getContain()->getHordeContainInterface();
	if (!horde)
		return false;
	if (!horde->hasSpotForUnit(docker))
		horde->assignSpotToUnit(docker);
	getEnterPosition(docker, position);
	if (index)
		*index = 0;
	return true;
}

// FUNCTION: BFME2 0x0049A8FA size=65 name=?getEnterPosition@HordeAIUpdate@@UAEXHPAUCoord3D@@@Z evidence=N:ledger
void HordeAIUpdate::getEnterPosition(Object *docker, Coord3D *position)
{
	Real angle;
	HordeContainInterface *horde = getObject()->getContain()->getHordeContainInterface();
	if (horde && position)
		*position = horde->getUnitsIntendedPosition(docker, &angle);
}

